// @webkit-project
import { test, expect, type Page } from '@playwright/test';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { unzipSync } from 'fflate';

/**
 * Password-protected 7z and RAR in the archive extractor (7-Zip as WebAssembly, loaded only for them).
 * Runs in Chromium and WebKit. The fixtures are in tests/fixtures/static; see CREDITS.md there.
 */

const staticFx = (name: string) => fileURLToPath(new URL(`./fixtures/static/${name}`, import.meta.url));

/** The three files inside the enc-* fixtures; docs/data.bin is the generated byte pattern they were packed from. */
const ENC_FILES: Record<string, Uint8Array> = {
  'hello.txt': new TextEncoder().encode('Hello from the secret archive.\nLine two.\n'),
  'docs/note.txt': new TextEncoder().encode('Ünïcode note: tide pool ✓\n'),
  'docs/data.bin': Uint8Array.from({ length: 2000 }, (_, i) => (i * 7 + (i >> 3) * 13 + 3) & 255),
};

async function open(page: Page) {
  const errors: string[] = [];
  const seen: { url: string; method: string; body: string | null }[] = [];
  page.on('pageerror', (e) => errors.push(e.message));
  page.on('console', (m) => {
    if (m.type() === 'error') errors.push(m.text());
  });
  page.on('request', (r) => seen.push({ url: r.url(), method: r.method(), body: r.postData() }));
  // The site skips analytics in automated browsers; pretend to be a person and record the events.
  await page.addInitScript(() => Object.defineProperty(Navigator.prototype, 'webdriver', { get: () => false }));
  await page.route('https://stats.keenankaufman.com/**', (route) =>
    route.fulfill({ contentType: 'text/javascript', body: 'window.__events=[];window.umami={track:(n,d)=>window.__events.push({n,d})};' }),
  );
  await page.goto('/tools/archive-extractor');
  await expect(page.locator('#tool')).toHaveAttribute('data-ready', 'true');
  return { errors, seen };
}

const usageRuns = (page: Page) =>
  page.evaluate(() => (window as unknown as { __events: { n: string; d: Record<string, string> }[] }).__events.filter((e) => e.n === 'tool_run').map((e) => e.d));

async function zipAll(page: Page): Promise<Record<string, Uint8Array>> {
  const [d] = await Promise.all([page.waitForEvent('download'), page.locator('#download-all').click()]);
  return unzipSync(new Uint8Array(readFileSync((await d.path())!)));
}

for (const fixture of ['enc-content.7z', 'enc-header.7z', 'enc-rar4.rar', 'enc-rar4-header.rar', 'enc-rar5.rar', 'enc-rar5-header.rar']) {
  test(`${fixture} opens with the right password, a missing or wrong one is named, and no bytes leave the tab`, async ({ page }) => {
    const { errors, seen } = await open(page);
    await page.locator('#file-input').setInputFiles(staticFx(fixture));
    await page.locator('#run').click();
    await expect(page.locator('#error')).toContainText('password-protected', { timeout: 60_000 });
    await page.locator('#password').fill('not-it');
    await page.locator('#run').click();
    await expect(page.locator('#error')).toContainText('password is wrong', { timeout: 60_000 });
    await expect(page.locator('#results')).not.toHaveClass(/is-active/);
    await page.locator('#password').fill('tide-pool');
    await page.locator('#run').click();
    await expect(page.locator('#results')).toContainText('3 files extracted', { timeout: 60_000 });
    const files = await zipAll(page);
    expect(Object.keys(files).sort()).toEqual(Object.keys(ENC_FILES).sort());
    for (const [name, bytes] of Object.entries(ENC_FILES)) expect(Buffer.from(files[name]!).equals(Buffer.from(bytes)), name).toBe(true);
    // Only class names reach analytics.
    await expect.poll(async () => (await usageRuns(page)).map((r) => r.error_class ?? r.outcome)).toEqual(['PasswordRequired', 'WrongPassword', 'ok']);
    for (const r of seen) {
      if (r.url.startsWith('blob:') || r.url.startsWith('data:')) continue;
      const host = new URL(r.url).hostname;
      if (host === 'stats.keenankaufman.com') continue;
      expect(host, `unexpected host ${host}`).toBe('localhost');
      expect(r.method, `${r.url} must be a plain GET`).toBe('GET');
      expect(r.body, `${r.url} must carry no body`).toBeNull();
    }
    expect(seen.some((r) => r.url.includes('/vendor/7z-wasm@1.2.0/7zz.wasm'))).toBe(true);
    // The page logs the two password errors it showed; anything else is a failure.
    expect(errors.filter((e) => !/^(PasswordRequired|WrongPassword): /.test(e))).toEqual([]);
  });
}

test('a plain 7z and RAR still open when a password is typed, and without one they do not load 7-Zip', async ({ page }) => {
  const { seen } = await open(page);
  await page.locator('#file-input').setInputFiles([staticFx('sample.7z'), staticFx('sample.rar')]);
  await page.locator('#run').click();
  await expect(page.locator('#results')).toContainText('3 files extracted', { timeout: 60_000 });
  expect(seen.some((r) => r.url.includes('/vendor/7z-wasm@'))).toBe(false);
  await page.locator('#password').fill('anything');
  await page.locator('#run').click();
  // 7-Zip also writes the RAR's symbolic link as a small file.
  await expect(page.locator('#results')).toContainText('4 files extracted', { timeout: 60_000 });
  const files = await zipAll(page);
  expect(Object.keys(files).sort()).toEqual(['file1', 'test.txt', 'testdir/test.txt', 'testlink']);
  expect(files['file1']!.length).toBe(2844);
  expect(seen.some((r) => r.url.includes('/vendor/7z-wasm@1.2.0/7zz.wasm'))).toBe(true);
});
